#!/usr/bin/env node

// ────────────────────────────────────────────────────────────────
// DO NOT EDIT THIS FILE.
//
// COPY of source-of-truth at
//   ~/.claude/standards/scripts/verify/verify-no-history-baked-in.mjs
//
// Local edits will be overwritten the next time
//   bash ~/.claude/standards/scripts/install-slice-gates.sh
// runs. Edit the ORIGINAL and re-install.
// ────────────────────────────────────────────────────────────────
/**
 * verify-no-history-baked-in — refuses history phrases in agent + standards docs.
 *
 * Walks ~/.claude/agents/ and ~/.claude/standards/ (when run from there) OR
 * the project's vendored .claude/agents/ + .claude/standards/ (when run from
 * a project repo) for forbidden patterns. Each match: file:line:pattern.
 * Exit 1 on any match.
 *
 * Targets baked-in narratives ("the OLD approach", "amendment v2", "shipped
 * real bugs", "doctrine reversal", dated parentheticals, etc.) that violate
 * the declarative-present-tense rule. Agents/standards/specs read as if
 * always this way; past decisions belong in commit messages, never in
 * checked-in docs.
 *
 * Usage:
 *   node ~/.claude/standards/scripts/verify/verify-no-history-baked-in.mjs
 *   node <project>/scripts/verify/verify-no-history-baked-in.mjs
 */

import { readdirSync, readFileSync, statSync, existsSync } from "node:fs";
import { join, relative, resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const __filename = fileURLToPath(import.meta.url);
const SCRIPT_DIR = dirname(__filename);

// Try two resolution strategies:
//   1. Project layout: <repo>/scripts/verify/verify-no-history-baked-in.mjs → repo at ../../..
//   2. Standards-source layout: ~/.claude/standards/scripts/verify/...    → standards at ../..
// In both cases scan <root>/.claude/agents + <root>/.claude/standards.
const PROJECT_ROOT_CANDIDATE = resolve(SCRIPT_DIR, "../../..");
const HOME_STANDARDS_CANDIDATE = resolve(SCRIPT_DIR, "../..");

const SCAN_ROOTS = [];
if (existsSync(join(PROJECT_ROOT_CANDIDATE, ".claude/agents")) || existsSync(join(PROJECT_ROOT_CANDIDATE, ".claude/standards"))) {
  SCAN_ROOTS.push(join(PROJECT_ROOT_CANDIDATE, ".claude/agents"));
  SCAN_ROOTS.push(join(PROJECT_ROOT_CANDIDATE, ".claude/standards"));
}
if (HOME_STANDARDS_CANDIDATE.endsWith("/.claude/standards")) {
  // Running from ~/.claude/standards/scripts/verify/ — scan the user-global agents + standards
  const userClaude = dirname(HOME_STANDARDS_CANDIDATE);
  SCAN_ROOTS.push(join(userClaude, "agents"));
  SCAN_ROOTS.push(HOME_STANDARDS_CANDIDATE);
}

// Hard bans — phrases with no legitimate present-tense use case in
// agent/standards docs. Each pattern is regex-tested per line.
const PATTERNS = [
  { name: "dated-amendment-parenthetical", re: /\(\d{4}-\d{2}-\d{2}\s+amendment\)/i },
  { name: "amendment-version", re: /\bamendment\s+v\d+\b/i },
  { name: "the-OLD-section", re: /\bthe\s+OLD\s+§\d+/ },
  { name: "the-OLD-approach", re: /\bthe\s+OLD\s+approach\b/ },
  { name: "the-NEW-approach", re: /\bthe\s+NEW\s+approach\b/ },
  { name: "previous-approach", re: /\bprevious\s+approach\b/i },
  { name: "previous-regime", re: /\bprevious\s+regime\b/i },
  { name: "the-new-regime", re: /\bthe\s+new\s+regime\b/i },
  { name: "the-old-regime", re: /\bthe\s+old\s+regime\b/i },
  { name: "doctrine-reversal", re: /\bdoctrine\s+reversal\b/i },
  { name: "had-to-nuke", re: /\bhad\s+to\s+nuke\b/i },
  { name: "shipped-real-bugs", re: /\bshipped\s+real\s+bugs\b/i },
  { name: "slice-NN-incident", re: /\bthe\s+slice-\d+\s+(incident|nuke)\b/i },
  { name: "proof-of-pattern-retrofit", re: /\bproof-of-pattern\s+retrofit\b/i },
  { name: "PHASE-X-retrofit", re: /\bPHASE\s+[A-Z]\s+(cross-cutting|retrofit)\b/ },
  { name: "vN-doctrine-reversal", re: /\bv\d+\s+doctrine\s+reversal\b/i },
  { name: "replacing-named-thing", re: /\(replacing\s+[A-Z]\w+\)/ },
  { name: "Updated-to-match-the-new", re: /\bUpdated\s+to\s+match\s+the\s+new\b/i },
  { name: "moved-and-got-renamed", re: /\bmoved\s+to\s+.*\s+and\s+got\s+renamed\b/i },
  { name: "Changes-from-the-old-shape", re: /\bChanges\s+from\s+the\s+old\s+shape\b/i },
  { name: "locked-on-date-parenthetical", re: /\(locked\s+\d{4}-\d{2}-\d{2}\)/i },
  { name: "Per-the-DATE-amendment", re: /\bPer\s+the\s+\d{4}-\d{2}-\d{2}.*\bamendment\b/i },
  { name: "Per-the-DATE-rule", re: /\bPer\s+the\s+\d{4}-\d{2}-\d{2}\s+[a-z][a-z-]*\s+(amendment|rule|gate|change|directive)\b/i },
  { name: "the-rule-I-keep-breaking", re: /\bthe\s+rule\s+I\s+keep\s+breaking\b/i },
  { name: "adapted-from-named-source", re: /\badapted\s+from\s+[A-Z]/i },
  { name: "ported-from-named-source", re: /\bported\s+from\s+[A-Z]/i },
  { name: "sourced-from-other-repo", re: /\bsourced\s+(verbatim\s+)?from\s+\S+\s+repo\b/i },
  { name: "brand-toptal", re: /\btoptal\b/i },
  { name: "brand-creator-dashboard", re: /\bcreator-dashboard\b/i },
  { name: "amendment-narrative", re: /\b(curated|sourced|brought\s+in|imported|migrated)\s+(verbatim\s+)?from\s+(another|other|the)\s+(repo|repository|machine|computer|codebase)\b/i },
  { name: "regime-adoption-narrative", re: /\b(adopted|adoption|adopting)\s+the\s+\S+\s+(regime|standards|verify\s+regime)\b/i },
];

const FILE_EXTENSIONS = [".md", ".yaml", ".yml", ".mjs"];

function walk(dir, out = []) {
  let entries;
  try {
    entries = readdirSync(dir);
  } catch {
    return out;
  }
  for (const entry of entries) {
    if (entry.startsWith(".") && entry !== ".gitkeep") continue;
    const path = join(dir, entry);
    let s;
    try {
      s = statSync(path);
    } catch {
      continue;
    }
    if (s.isDirectory()) walk(path, out);
    else if (FILE_EXTENSIONS.some((ext) => entry.endsWith(ext))) out.push(path);
  }
  return out;
}

// The verifier defines its own banned phrases as pattern names, so its
// own source must be excluded from its own scan. Any future file that
// legitimately names the patterns goes in here too.
const SELF_EXEMPT_FILES = new Set([
  "verify-no-history-baked-in.mjs",
]);

function scanFile(path) {
  if (SELF_EXEMPT_FILES.has(path.split("/").pop())) return [];
  const content = readFileSync(path, "utf8");
  const lines = content.split("\n");
  const hits = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    for (const { name, re } of PATTERNS) {
      if (re.test(line)) hits.push({ line: i + 1, pattern: name, content: line.trim() });
    }
  }
  return hits;
}

let totalHits = 0;
let totalFiles = 0;
const violations = [];

for (const root of SCAN_ROOTS) {
  if (!existsSync(root)) continue;
  const files = walk(root);
  totalFiles += files.length;
  for (const file of files) {
    const hits = scanFile(file);
    if (hits.length > 0) {
      violations.push({ file, hits });
      totalHits += hits.length;
    }
  }
}

if (totalHits > 0) {
  process.stderr.write(
    `\n❌ verify-no-history-baked-in: ${totalHits} hit(s) in ${violations.length} file(s)\n`,
  );
  for (const v of violations) {
    process.stderr.write(`\n  ${v.file}\n`);
    for (const h of v.hits) {
      process.stderr.write(`    line ${h.line}: [${h.pattern}]\n`);
      process.stderr.write(`      ${h.content}\n`);
    }
  }
  process.stderr.write(
    `\nAgent + standards docs read declarative present-tense as if always this way.\n` +
    `Past decisions belong in commit messages, never in checked-in docs.\n`,
  );
  process.exit(1);
}

process.stdout.write(
  `✅ verify-no-history-baked-in — ${totalFiles} file(s) clean across ${SCAN_ROOTS.length} root(s)\n`,
);
process.exit(0);
